"""External tests for SCEVAN synthetic matrices (known ground truth).

SCEVAN synthetic datasets are generated by the SCEVAN R package to benchmark
CNV callers. Each matrix plants a known tumor signal into approximately 50%
of cells; the remaining cells are normal. This gives us a ground-truth label
for precision/recall evaluation.

Reference: De Falco et al., Nature Communications 2023 (SCEVAN).

Requires: DATA_ROOT/scevan-synthetic/h5ad/*.h5ad (skip if absent).
"""

import numpy as np
import pytest

from tests.external.ground_truth import compute_tumor_normal_recall, run_full_pipeline


# SCEVAN synthetic matrices plant tumor signal into roughly half the cells.
# The exact split depends on how the h5ad was generated; we infer it from
# metadata when available, otherwise assume 50%.
EXPECTED_TUMOR_FRACTION = 0.50

# Acceptance thresholds.
MIN_MEAN_TUMOR_RECALL = 0.70   # average across 10 matrices
MIN_PER_MATRIX_RECALL = 0.50   # no single matrix should be catastrophically bad


def _infer_tumor_barcodes(prediction_df, h5ad_path):
    """Extract ground-truth tumor barcodes from h5ad metadata if present.

    SCEVAN synthetic h5ad files may store ground-truth labels in obs columns
    named 'true_label', 'cell_type', 'is_tumour', or similar. This function
    tries several common field names including boolean flag columns (is_tumour,
    is_tumor) and falls back to positional inference (bottom half = normal,
    top half = tumor) when none are found.

    Args:
        prediction_df: classify_cells() output (indexed by barcode).
        h5ad_path: Path to the h5ad file (used to read obs metadata).

    Returns:
        (tumor_barcodes, normal_barcodes): two lists of barcode strings.
        Either may be None if not determinable.
    """
    from anndata import read_h5ad

    adata = read_h5ad(h5ad_path)
    obs = adata.obs

    # Priority 1: boolean flag columns — is_tumour / is_tumor are the canonical
    # SCEVAN synthetic ground-truth columns and are the most reliable.
    for bool_col in ("is_tumour", "is_tumor", "is_malignant", "tumor_flag"):
        if bool_col in obs.columns:
            col_vals = obs[bool_col]
            # Accept boolean or integer-boolean (1/0) or string True/False.
            tumor_bc = []
            normal_bc = []
            for bc, val in col_vals.items():
                is_t = (val is True) or (val == 1) or (str(val).lower() == "true")
                if is_t:
                    tumor_bc.append(bc)
                else:
                    normal_bc.append(bc)
            if tumor_bc:
                return tumor_bc, normal_bc if normal_bc else None

    # Priority 2: string label columns with explicit tumor/normal keywords.
    gt_candidates = ["true_label", "ground_truth", "cell_type", "tumor_normal",
                     "label", "class", "type"]
    gt_col = None
    for col in gt_candidates:
        if col in obs.columns:
            unique_vals = obs[col].unique()
            # Only accept columns that look like a binary tumor/normal split.
            lower_vals = {str(v).lower() for v in unique_vals}
            if lower_vals & {"tumor", "malignant", "cancer", "tumour"}:
                gt_col = col
                break

    if gt_col is not None:
        # Map ground-truth labels to tumor / normal.
        tumor_keywords = {"tumor", "malignant", "cancer", "tumour", "1", "true"}
        normal_keywords = {"normal", "non-malignant", "stromal", "immune",
                          "endothelial", "0", "false"}
        tumor_bc = []
        normal_bc = []
        for bc, row in obs.iterrows():
            val = str(row[gt_col]).lower()
            if val in tumor_keywords:
                tumor_bc.append(bc)
            elif val in normal_keywords:
                normal_bc.append(bc)
        return tumor_bc if tumor_bc else None, normal_bc if normal_bc else None

    # Fallback: positional split — assume bottom 50% are normal, top 50% tumor.
    # This matches the typical SCEVAN synthetic generation protocol.
    all_barcodes = list(prediction_df.index)
    n = len(all_barcodes)
    split = n // 2
    return all_barcodes[split:], all_barcodes[:split]


def _run_one_synthetic(h5ad_path, out_dir, idx):
    """Run pipeline on one synthetic matrix, return tumor recall.

    Args:
        h5ad_path: Path to one synthetic h5ad.
        out_dir: Base output directory; a subdirectory is created per matrix.
        idx: Integer index used for naming the output subdirectory.

    Returns:
        float: tumor recall for this matrix (0.0 if no ground truth available).
    """
    sample_name = f"scevan_synthetic_{idx:03d}"
    run_out = out_dir / sample_name
    run_out.mkdir(parents=True, exist_ok=True)

    prediction_df, chr_matrix, chroms_present, segments, qc = run_full_pipeline(
        h5ad_path=h5ad_path,
        sample_name=sample_name,
        out_dir=run_out,
    )

    tumor_barcodes, normal_barcodes = _infer_tumor_barcodes(prediction_df, h5ad_path)

    if tumor_barcodes is None:
        # No ground-truth available — skip this matrix's contribution.
        return None

    metrics = compute_tumor_normal_recall(
        prediction_df=prediction_df,
        tumor_barcodes=tumor_barcodes,
        normal_barcodes=normal_barcodes,
    )
    return metrics["tumor_recall"]


def test_scevan_synthetic_tumor_recall(scevan_h5ad_list, tmp_path):
    """On synthetic MM matrices, average tumor recall >= 0.70.

    Runs the full pipeline on up to 10 SCEVAN synthetic h5ad files. For each
    matrix, infers ground-truth tumor/normal labels from obs metadata or from
    positional convention (50/50 split). Averages the per-matrix tumor recall
    and asserts the mean >= 0.70.

    A per-matrix floor of 0.50 is also checked so that one catastrophically
    bad matrix cannot be masked by good performance on the others.
    """
    recalls = []
    per_matrix_results = []

    for idx, h5ad_path in enumerate(scevan_h5ad_list[:10]):
        recall = _run_one_synthetic(h5ad_path, tmp_path, idx)
        if recall is None:
            # No ground truth for this matrix; skip without counting it.
            continue
        recalls.append(recall)
        per_matrix_results.append((h5ad_path.name, recall))

    if not recalls:
        pytest.skip(
            "No SCEVAN synthetic matrices yielded ground-truth labels; "
            "cannot compute tumor recall."
        )

    mean_recall = sum(recalls) / len(recalls)

    # Per-matrix floor: flag any matrix that performed catastrophically badly.
    bad_matrices = [
        (name, r) for name, r in per_matrix_results if r < MIN_PER_MATRIX_RECALL
    ]

    # Report per-matrix results in the failure message for debugging.
    detail = "; ".join(f"{name}={r:.2f}" for name, r in per_matrix_results)

    assert mean_recall >= MIN_MEAN_TUMOR_RECALL, (
        f"Mean tumor recall {mean_recall:.2f} < {MIN_MEAN_TUMOR_RECALL} "
        f"across {len(recalls)} matrices. Per-matrix: {detail}"
    )

    # Warn (but do not fail) on individual bad matrices — the mean gate is
    # the primary acceptance criterion; per-matrix floor is diagnostic.
    if bad_matrices:
        bad_detail = "; ".join(f"{name}={r:.2f}" for name, r in bad_matrices)
        # Use a soft message via the assertion rather than a hard fail here.
        # The mean gate above already enforces aggregate performance.
        print(
            f"\n[WARNING] {len(bad_matrices)} matrix/matrices below "
            f"per-matrix floor of {MIN_PER_MATRIX_RECALL}: {bad_detail}"
        )


def test_scevan_synthetic_normal_recall(scevan_h5ad_list, tmp_path):
    """On synthetic matrices, average normal recall >= 0.60.

    A complement to the tumor recall test; ensures the classifier is not
    labelling everything as tumor to inflate tumor recall.
    """
    recalls = []

    for idx, h5ad_path in enumerate(scevan_h5ad_list[:10]):
        sample_name = f"scevan_normal_chk_{idx:03d}"
        run_out = tmp_path / sample_name
        run_out.mkdir(parents=True, exist_ok=True)

        prediction_df, _, _, _, _ = run_full_pipeline(
            h5ad_path=h5ad_path,
            sample_name=sample_name,
            out_dir=run_out,
        )

        _, normal_barcodes = _infer_tumor_barcodes(prediction_df, h5ad_path)
        if normal_barcodes is None:
            continue

        metrics = compute_tumor_normal_recall(
            prediction_df=prediction_df,
            normal_barcodes=normal_barcodes,
        )
        if metrics["normal_recall"] is not None:
            recalls.append(metrics["normal_recall"])

    if not recalls:
        pytest.skip("No ground-truth normal labels found in SCEVAN synthetic matrices.")

    mean_recall = sum(recalls) / len(recalls)
    assert mean_recall >= 0.60, (
        f"Mean normal recall {mean_recall:.2f} < 0.60 across {len(recalls)} matrices. "
        "The classifier may be over-calling tumor."
    )


def test_scevan_synthetic_pipeline_completes_all(scevan_h5ad_list, tmp_path):
    """All SCEVAN synthetic matrices run without raising an exception."""
    for idx, h5ad_path in enumerate(scevan_h5ad_list[:10]):
        sample_name = f"scevan_sanity_{idx:03d}"
        run_out = tmp_path / sample_name
        run_out.mkdir(parents=True, exist_ok=True)

        # Should complete without error; any exception propagates as test failure.
        _, _, _, segments, qc = run_full_pipeline(
            h5ad_path=h5ad_path,
            sample_name=sample_name,
            out_dir=run_out,
        )

        assert qc["n_cells_filtered"] > 0, (
            f"{h5ad_path.name}: all cells were filtered out "
            f"(n_cells_raw={qc['n_cells_raw']})"
        )
        assert qc["n_segments"] > 0, (
            f"{h5ad_path.name}: no segments detected; segmentation failed"
        )
